    // Additional extra variant pairs commonly seen in Traditional lyrics & credits
    private val EXTRA_T2S = mapOf(
        '詞' to '词', '編' to '编', '製' to '制', '錄' to '录', '監' to '监',
        '聲' to '声', '鍵' to '键', '盤' to '盘', '鋼' to '钢', '絃' to '弦',
        '貝' to '贝', '譯' to '译', '權' to '权', '許' to '许', '訊' to '讯',
        '樂' to '乐', '團' to '团', '廳' to '厅', '劃' to '划', '統' to '统',
        '籌' to '筹', '設' to '设', '計' to '计', '視' to '视', '覺' to '觉',
        '畫' to '画', '總' to '总', '鳴' to '鸣', '謝' to '谢', '廣' to '广',
        '產' to '产', '發' to '发', '單' to '单', '獨' to '独', '擊' to '击',
        '號' to '号', '長' to '长', '經' to '经', '紀' to '纪', '營' to '营',
        '銷' to '销', '運' to '运', '傳' to '传', '顧' to '顾', '問' to '问',
        '藝' to '艺', '攝' to '摄', '廠' to '厂', '軌' to '轨', '調' to '调',
        '題' to '题', '繪' to '绘', '國' to '国', '際' to '际', '書' to '书',
        '餘' to '余', '傑' to '杰', '換' to '换', '臺' to '台', '為' to '为',
        '裏' to '里', '裡' to '里', '說' to '说', '牆' to '墙', '託' to '托',
        '著' to '著', '昇' to '升', '髒' to '脏', '藉' to '借'
    )

    private val t2sMap: Map<Char, Char> by lazy {
        val len = minOf(SIMPLIFIED.length, TRADITIONAL.length)
        buildMap(len + EXTRA_T2S.size) {
            for (i in 0 until len) {
                val t = TRADITIONAL[i]
                val s = SIMPLIFIED[i]
                if (t != s) putIfAbsent(t, s)
            }
            putAll(EXTRA_T2S)
        }
    }

    fun toSimplified(text: String): String {
        if (text.isEmpty()) return text
        var changed = false
        val sb = StringBuilder(text.length)
        for (ch in text) {
            val mapped = t2sMap[ch]
            if (mapped != null) {
                sb.append(mapped)
                changed = true
            } else {
                sb.append(ch)
            }
        }
        return if (changed) sb.toString() else text
    }
